import { Component, Input, SimpleChanges } from '@angular/core';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { ActivatedRoute } from '@angular/router';
import { HelpcenterService } from '../../../services/helpcenter/helpcenter.service';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
@Component({
  selector: 'helpcenterdetail',
  standalone: true,
  imports: [],
  templateUrl: './helpcenterdetail.component.html',
  styleUrl: './helpcenterdetail.component.scss'
})
export class HelpcenterdetailComponent {

  cTitle: string = '';
  link: any = '';
  isLoaded: boolean = false;


  // ngOnChanges(changes: SimpleChanges): void {
  //   if (changes['selectedsubmodule']) {
  //     this.link = this.sanitizeUrl(this.selectedsubmodule.cLink);  
  //   }
  // }

  constructor(private sanitizer: DomSanitizer, private route: ActivatedRoute, private helpcenterService: HelpcenterService, private cf: CommonfunctionService) {

    this.route.queryParams.subscribe(params => {

      this.helpcenterService.getsubmodule_detail(params['nSMid']).then((res: any) => {
        this.link = this.sanitizeUrl(res.cLink);
        this.cTitle = res.cTitle;
      });

    });
  }




  sanitizeUrl(url: string): SafeResourceUrl {
    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  ngOnInit(): void {

  }

  goToHome() {
    this.cf.goto('/user/dashboard');
  }

  onLoad() {
    setTimeout(() => {
      this.isLoaded = true;
    }, 1000);
  }

}
